# 第十一期新图标（自绘、可商用、无文字）：取餐号、取餐窗口、餐盒、点击波纹、弱信号、请求信封、账本、硬币
# 复用（自绘）：phone / phone-busy / server / gate（第十期）、queue / guest（第九期）
import os
T=dict(bg="#0B1020",s2="#1F2937",text="#E5E7EB",text2="#9CA3AF",muted="#6B7280",primary="#22D3EE",secondary="#3B82F6",success="#22C55E",accent="#F59E0B",danger="#F87171")
OUT=os.path.join(os.path.dirname(os.path.abspath(__file__)),"assets");os.makedirs(OUT,exist_ok=True)
def svg(n,b): open(os.path.join(OUT,n),"w").write(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">\n{b}\n</svg>\n')
# 取餐号：带锯齿边的小票，中间三道横线代替号码（不写字）
svg("ticket.svg",f'<path d="M110 60 H402 V452 L372 432 L342 452 L312 432 L282 452 L256 432 L230 452 L200 432 L170 452 L140 432 L110 452 Z" fill="{T["s2"]}" stroke="{T["accent"]}" stroke-width="14" stroke-linejoin="round"/><circle cx="256" cy="160" r="54" fill="{T["accent"]}"/><rect x="160" y="260" width="192" height="22" rx="11" fill="{T["text2"]}"/><rect x="160" y="320" width="140" height="22" rx="11" fill="{T["muted"]}"/>')
svg("window.svg",f'<rect x="40" y="70" width="432" height="60" rx="12" fill="{T["secondary"]}"/><rect x="60" y="130" width="392" height="230" fill="{T["s2"]}" stroke="{T["text2"]}" stroke-width="12"/><rect x="120" y="180" width="272" height="130" rx="16" fill="{T["bg"]}"/><rect x="30" y="360" width="452" height="44" rx="10" fill="{T["muted"]}"/><rect x="70" y="404" width="40" height="80" fill="{T["text2"]}"/><rect x="402" y="404" width="40" height="80" fill="{T["text2"]}"/>')
svg("meal.svg",f'<path d="M70 250 H442 C442 370 360 440 256 440 C152 440 70 370 70 250 Z" fill="{T["accent"]}"/><rect x="50" y="232" width="412" height="30" rx="15" fill="{T["text2"]}"/><path d="M190 200 C170 160 210 140 190 100 M256 200 C236 160 276 140 256 100 M322 200 C302 160 342 140 322 100" stroke="{T["muted"]}" stroke-width="16" fill="none" stroke-linecap="round"/>')
svg("tap.svg",f'<circle cx="256" cy="200" r="70" fill="none" stroke="{T["primary"]}" stroke-width="14"/><circle cx="256" cy="200" r="130" fill="none" stroke="{T["primary"]}" stroke-width="10" opacity="0.5"/><path d="M226 200 V400 C226 450 286 470 326 450 L380 400 C400 380 390 350 360 350 L286 350 V200 C286 170 226 170 226 200 Z" fill="{T["text"]}"/>')
svg("signal.svg",f'<rect x="80" y="360" width="70" height="90" rx="10" fill="{T["accent"]}"/><rect x="180" y="280" width="70" height="170" rx="10" fill="{T["muted"]}"/><rect x="280" y="190" width="70" height="260" rx="10" fill="{T["muted"]}"/><rect x="380" y="100" width="70" height="350" rx="10" fill="{T["muted"]}"/><path d="M90 90 L230 230 M230 90 L90 230" stroke="{T["danger"]}" stroke-width="26" stroke-linecap="round"/>')
svg("request.svg",f'<rect x="50" y="130" width="412" height="270" rx="24" fill="{T["s2"]}" stroke="{T["primary"]}" stroke-width="14"/><path d="M60 145 L256 290 L452 145" fill="none" stroke="{T["primary"]}" stroke-width="14" stroke-linejoin="round"/>')
svg("ledger.svg",f'<rect x="90" y="50" width="340" height="412" rx="20" fill="{T["s2"]}" stroke="{T["success"]}" stroke-width="14"/><rect x="90" y="50" width="60" height="412" rx="12" fill="{T["success"]}"/>'+"".join(f'<rect x="190" y="{120+i*70}" width="200" height="20" rx="10" fill="{T["text2"]}"/>' for i in range(5)))
svg("coin.svg",f'<circle cx="256" cy="256" r="200" fill="{T["accent"]}"/><circle cx="256" cy="256" r="150" fill="none" stroke="{T["bg"]}" stroke-width="18"/><rect x="236" y="160" width="40" height="192" rx="12" fill="{T["bg"]}"/>')
# 待支付手机：同 phone.svg 外框，屏幕是一张票（未支付，无对勾）
svg("phone-pending.svg",f'<rect x="136" y="24" width="240" height="464" rx="40" fill="#1F2937" stroke="#22D3EE" stroke-width="16"/><rect x="160" y="80" width="192" height="340" rx="12" fill="#111827"/><rect x="196" y="140" width="120" height="120" rx="14" fill="none" stroke="{T["accent"]}" stroke-width="12"/><circle cx="256" cy="200" r="22" fill="{T["accent"]}"/><rect x="190" y="300" width="132" height="16" rx="8" fill="#6B7280"/><rect x="210" y="336" width="92" height="16" rx="8" fill="#6B7280"/><rect x="226" y="446" width="60" height="12" rx="6" fill="#9CA3AF"/>')
